import { processEvents } from "./process_events";

const rnd = (() => {
  let s = 42;
  return () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
})();
const ri = (n: number) => Math.floor(rnd() * n);

const ITEMS = ["apple", "pear", "kiwi", "grape", "plum"];

function randEvent(depth: number): any {
  const t = rnd();
  if (t < 0.34) {
    return { type: "order", id: "o" + ri(9000), item: ITEMS[ri(ITEMS.length)], qty: 1 + ri(6) };
  } else if (t < 0.46) {
    return { type: "cancel", id: "o" + ri(9000) };
  } else if (t < 0.58) {
    return { type: "restock", item: ITEMS[ri(ITEMS.length)], qty: 1 + ri(5) };
  } else if (t < 0.82) {
    const qty = rnd() < 0.3 ? undefined : 1 + ri(6);
    const e: any = { type: "ship", id: "o" + ri(9000) };
    if (qty !== undefined) e.qty = qty;
    return e;
  } else {
    return { type: "expire", id: "o" + ri(9000) };
  }
}

function randCase(): any {
  const stock: any = {};
  if (rnd() < 0.9) {
    for (const it of ITEMS) if (rnd() < 0.5) stock[it] = ri(8);
  } else {
    // sometimes empty/invalid stock
    return { stock: rnd() < 0.5 ? "nope" : null, events: [randEvent(0)] };
  }
  const events: any[] = [];
  const n = 1 + ri(25);
  for (let i = 0; i < n; i++) events.push(randEvent(i));
  if (rnd() < 0.08) events[ri(events.length)] = rnd() < 0.5 ? "zzz" : 42;
  return { stock, events };
}

const cases: any[] = [];
for (let i = 0; i < 30000; i++) cases.push(randCase());
// handpicked edge cases
cases.push({ stock: { a: 5 }, events: [] });
cases.push({ stock: { a: 0 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }] });
cases.push({ stock: { a: 5 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }, { type: "order", id: "y", item: "a", qty: 3 }] });
cases.push({ stock: { a: 5 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }, { type: "order", id: "y", item: "a", qty: 3 }, { type: "restock", item: "a", qty: 3 }] });
cases.push({ stock: { a: 5 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }, { type: "cancel", id: "x" }, { type: "order", id: "y", item: "a", qty: 3 }] });
cases.push({ stock: { a: 5 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }, { type: "ship", id: "x" }, { type: "order", id: "y", item: "a", qty: 3 }] });
cases.push({ stock: { a: 5 }, events: [{ type: "order", id: "x", item: "a", qty: 5 }, { type: "expire", id: "x" }, { type: "order", id: "y", item: "a", qty: 3 }] });

const fs = require("fs");
fs.writeFileSync(require("path").join(__dirname, "cases.json"), JSON.stringify(cases));
console.log("generated", cases.length, "cases");

